                  "memo": "■ログインID設定のルール\n ・ 半角のみ\n ・ 英大文字、英小文字、数字、記号のみ\n ・ スペースは使用不可\n ・ 7文字以上100文字以下\n\n■パスワード設定のルール\n ・ 半角\n ・ 英字、数字、記号\n ・ 円マーク、バックスラッシュは使用不可\n ・ 8文字以上72文字以内\n ・ 強度メーターでOKと判定されたもの"
