                  "text": "＜問い合わせ内容を要約して復唱確認＞\nメールアドレス（またはログインID）をお忘れになってしまい、NHK ONE アカウントにログインできなくなってしまった、ということですね。\n\n＜メールアドレス／ログインID忘れの対応＞\nメールアドレス（またはログインID）をお忘れになった場合は、ログイン画面下の 「メールアドレスをお忘れの方はこちら」 よりお手続きください。\n携帯電話番号または復旧用メールアドレスと、パスワードをご入力いただくと、携帯電話番号の場合はSMSで、復旧用メールアドレスの場合はメールで送付される認証コードを入力いただくことで、登録メールアドレスやログインIDを再設定いただけます。\n再設定されたメールアドレスやログインIDとパスワードでログインしてください。",
