              "text": "<b>＜移行対象だがメアド利用不可＞</b>\n移行手続きはご利用いただけませんので、現在のNHK ONEアカウントをそのままご利用いただくようお願いいたします。\nなお、移行アカウントに受信契約情報が連携された状態となっておりますので、連携解除が必要となります。 \n担当窓口へご連絡いただき、移行アカウントの受信契約情報の削除を行っていただくようお願いいたします。\n移行アカウントの受信契約情報を削除した後、受信料アカウントの作成・」連携の手続きを行っていただくようにお願いいたします。",
