              "text": "＜問い合わせ内容を要約して復唱確認＞\n予習復習などの自主学習の際に、学校で配布された端末でNHK ONEのサービスを利用してもよいか、というご確認（ご質問）ですね。\nありがとうございます。\n\n＜利用について＞\n学校教育の一環として指示している場合は、ご利用意向の確認で用途「学校で」の用途を選択いただき、ご利用ください。\n受信契約については学校でお手続きが必要になります。",
