              "text": "＜問い合わせ内容を要約して復唱確認＞\n学校職員の方が「学校利用」としてサービスを利用してよいか、というご確認（ご質問）ですね。\nありがとうございます。\n\n＜利用可能＞\n学校の先生や生徒が、授業の過程において利用することは問題ありません。",
