              "text": "＜問い合わせ内容を要約して復唱確認＞\n「学校コード」「確認キー」がどのように保存されるのかご確認（ご質問）ですね。\nありがとうございます。\n\n＜保存方法について＞\n「学校コード」「確認キー」の保存につきましては、学校コードと確認キーを入力いただいたのち、ブラウザのcookieやアプリの保存領域に情報が保存されます。\n\n＜保存されない場合について＞\n従いまして、サイトであれば、cookieを消去した場合や、ブラウザのプライベートモード（シークレットモード）、入力したブラウザとは別のブラウザをご利用の場合、アプリであれば、アンインストールして再インストールした場合は、再度入力が必要となります。",
