      "body": "**********************************************************************\nこのメールは送信専用アドレスからお送りしています。このメールへの返信はできません。\n**********************************************************************\nNHKをご利用いただきありがとうございます。\n\n変更手続きで入力されたメールアドレスには変更できません。\n以下のいずれかのケースにあたると考えられます。\n\n1.\n同じメールアドレスで、すでにアカウントが作成されています。\nNHK ONEアカウントのパスワードをお忘れの方は、ログイン画面からお手続きください。\nhttps://portal.web.nhk/login\n\n2.\nNHK ONEが開始する以前の、旧NHKプラス アカウントで使われていたメールアドレスです。\n下記の専用のパスワード再設定ページからNHK ONEアカウントを作成いただくことが可能です。\nhttps://portal.web.nhk/kakunin\n\n旧NHKプラスからの移行対象のアカウントとメールアドレスについて、詳しくは下記ページをご参照ください。\nhttps://www.nhk.or.jp/nhkone/how-to-use/article/P001-0001/\n\n3.\n過去に、NHK ONEアカウントをご自身で削除した場合、そのNHK ONEアカウントで登録されたメールアドレスは、セキュリティ上の理由などから、削除から1か月間利用できません。\nお手数ですが別のメールアドレスをご利用ください。\n\n4.\n入力されたメールアドレスは、すでに復旧用メールアドレスに設定されています。別のメールアドレスを設定してください。\n\nご利用のアカウントの詳しい情報はこちらをご覧ください。\nhttps://portal.web.nhk\n\n\n────────────────────────────────\nNHK ONEアカウントに関するお問い合わせ\n電話番号: 0570-099-033 （ナビダイヤルをご利用になれない方は 050-3786-5007）\n受付時間: 午前9時～午後8時（土・日・祝も受付）\n────────────────────────────────\n\n────────────────\n発行元 ： NHK\n────────────────\n Copyright NHK (Japan Broadcasting Corporation) All rights reserved.  ",
