      "catColor": "#4361ee",
      "title": "1.1.10.2",
      "subject": "アカウント移行手続き 内容確認のお願い【NHK ONE】",
      "body": "**********************************************************************\nこのメールは、旧NHKプラスからNHK ONEへのアカウント移行手続きをされた方に自動送信しています。\n（このメールは送信専用アドレスからお送りしています。このメールへの返信はできません。）\n**********************************************************************\nNHKをご利用いただきありがとうございます。\n\n入力されたメールアドレスでは、NHK ONEアカウントのパスワード設定ができませんでした。\n以下のいずれかのケースにあたると考えられます。\n\n1.\nお使いのメールアドレスですでにパスワード設定手続きが行われ、旧NHKプラスからのアカウント移行手続きが完了しています。\n\nNHK ONEアカウントのパスワードをお忘れの方は、ログイン画面からお手続きください。\nhttps://portal.web.nhk/login\n\n2.\nお使いのメールアドレスは、旧NHKプラスからの移行対象ではありません。\n別のメールアドレスで旧NHKプラスをご登録されていた方は、そのメールアドレスで再度、移行手続きをお願いします。\n\n旧NHKプラスをご利用されたことのない方は、NHK ONEアカウントの新規登録をお願いします。\n下記ページを開き、「アカウントを登録する」ボタンからお手続きいただけます。\nhttps://portal.web.nhk/signup\n\n旧NHKプラスからの移行対象のアカウントとメールアドレスについて、詳しくは下記ページをご参照ください。\nhttps://www.nhk.or.jp/nhkone/how-to-use/article/P001-0001/\n\nNHK ONEアカウントの登録お手続きでお困りの方は下記をご参照ください。\nhttps://www.nhk.or.jp/nhkone/how-to-use/\n\n────────────────────────────────\nNHK ONEアカウントの登録・設定に関するお問い合わせ\n電話番号: 0570-099-033 （ナビダイヤルをご利用になれない方は 050-3786-5007）\n受付時間: 午前9時～午後8時（土・日・祝も受付）\n────────────────────────────────\n\n────────────────\n発行元 ： NHK\n────────────────\n Copyright NHK (Japan Broadcasting Corporation) All rights reserved.\n",
      "note": "移行手続き失敗した場合に認証コードの代わりに飛ぶメール "
