      "subject": "パスワード設定完了のお知らせ【NHK ONE】",
      "body": "**********************************************************************\nこのメールは送信専用アドレスからお送りしています。このメールへの返信はできません。\n**********************************************************************\nNHKをご利用いただきありがとうございます。\n\n手続きが行われ、NHK ONEアカウントのパスワード設定が完了しました。\n\nひきつづきNHK ONEをご利用ください。\n\nご利用のアカウントの詳しい情報はこちらをご覧ください。\nhttps://portal.web.nhk\n\nログインIDを任意で設定することもできます。ログインIDを設定すると、メールアドレス以外にも任意の文字列でログインできます。\n1. ログインIDの変更ページ https://portal.web.nhk/account/info/change-id にアクセスしてください\n2. メールアドレスとパスワードを入力してログインすると、認証コードがメール送信されます\n3. 認証コードを入力したのち、ログインIDを設定してください\n\n\n────────────────────────────────\nNHK ONE ご利用についてお困りのときは、下記ページをご参照ください。\nhttps://www.nhk.or.jp/nhkone/how-to-use/\n────────────────────────────────\nNHK ONEアカウントに関するお問い合わせ\n電話番号: 0570-099-033 （ナビダイヤルをご利用になれない方は 050-3786-5007）\n受付時間: 午前9時～午後8時（土・日・祝も受付）\n────────────────────────────────\n\n\n────────────────\n発行元 ： NHK\n────────────────\n Copyright NHK (Japan Broadcasting Corporation) All rights reserved.",
