      "subject": "ID申請受付完了のお知らせ【受信料アカウント】",
      "body": "ーーーーーーーーーーーーーーーーーーーーーーーーーーーーーーー\nこのメールは、ＮＨＫより自動送信しています。\nこのメールに返信していただきましてもお答えできません。\n心当たりのない場合は、下記お問い合わせ先へご連絡ください。\nーーーーーーーーーーーーーーーーーーーーーーーーーーーーーーー\nこのたびは、受信料アカウントの申請をしていただき、ありがとうございます。\n\n申請を受け付けましたので、お知らせします。\n\n「受信料の窓口」　にアクセスし、ページ上部の「受信料アカウント」から、以下の受信料アカウントＩＤと初期パスワードでログインし、パスワードの変更など初回設定を行ってください。\n\n　● 受信料アカウントＩＤ　　　ご登録のメールアドレスまたは設定された任意の文字列\n　● 初期パスワード　　((#INITIAL_PASSWORD#))\n\nログイン後、「NHK ONEアカウント設定ページ」ボタンにお進みください。遷移先のページ「受信契約の確認（受信契約情報の登録・連携）」の「受信料アカウントと連携する」から再度ログインすると、お手続き完了です。NHK ONEを引き続きご利用ください。\n\nご契約を確認できましたら、ご登録のメールアドレスへご連絡いたします。\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n日本放送協会「受信料の窓口」\nhttps://www.nhk-cs.jp\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n◆よくある質問はこちら\nhttps://www.nhk-cs.jp/support/faq/\n\n◆このメールについてのお問い合わせはこちらへ\nTEL:0570-099-033(ナビダイヤル)\n自動音声ガイダンスで「2」を押してください。\n----------------------------------------------------------------------\n午前9時～午後8時（土・日・祝日も受付）\nなお、12月31日から1月3日はご利用いただけません。\n固定電話からは、全国どこでも市内通話料金でご利用いただけます。\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
