      "subject": "メールアドレス重複のお知らせ【受信料アカウント】",
      "body": "ーーーーーーーーーーーーーーーーーーーーーーーーーーーーーーー\nこのメールは、ＮＨＫより自動送信しています。\nこのメールに返信していただきましてもお答えできません。\n心当たりのない場合は、下記お問い合わせ先へご連絡ください。\nーーーーーーーーーーーーーーーーーーーーーーーーーーーーーーー\n((#LOGIN_ID#)) 様\n\n受信料アカウントをご利用いただき、ありがとうございます。\n\nお客様のご入力いただいたメールアドレスは、\n以下のいずれかのケースにあたると考えられ、手続きを進めることができません。\n\n１）同じメールアドレスですでに手続きが進んでいるＩＤがある\n受信契約に登録できるメールアドレスは、ひとつです。\nＮＨＫからお送りした過去のメールをご確認ください。\n（旧NHKプラスＩＤが受信料アカウントに移行されている場合がございます。）\n\n２）ご自宅とは別に単身赴任などで複数の受信契約を締結している\n複数のご契約をお持ちの場合、同じメールアドレスはお使いになれません。\n\nＩＤやパスワードをお忘れの方は、「受信料の窓口」　にアクセスし、ページ上部の「受信料アカウント」からログイン画面に進み、「ＩＤを忘れた方」「パスワードを忘れた方」からお手続きいただけます。\n\nメールの内容にお心当たりがない場合は、下記お問い合わせ先へご連絡ください。\n\nご不明な点がございましたら、メール下部に記載の「◆よくある質問はこちら」もあわせてご確認ください。\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n日本放送協会「受信料の窓口」\nhttps://www.nhk-cs.jp\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n◆よくある質問はこちら\nhttps://www.nhk-cs.jp/support/faq/\n\n◆このメールについてのお問い合わせはこちらへ\nTEL:0570-099-033(ナビダイヤル)\n自動音声ガイダンスで「2」を押してください。\n----------------------------------------------------------------------\n午前9時～午後8時（土・日・祝日も受付）\nなお、12月31日から1月3日はご利用いただけません。\n固定電話からは、全国どこでも市内通話料金でご利用いただけます。\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
